// Intercept fetch to add auth headers and cookies automatically
const originalFetch = window.fetch;
window.fetch = async function() {
    let [resource, config] = arguments;
    
    // Intercept all requests to our /api/ backend
    if (typeof resource === 'string' && (resource.startsWith('/api/') || resource.includes('/api/'))) {
        config = config || {};
        config.credentials = config.credentials || 'same-origin';
        config.headers = config.headers || {};
        
        let userStr = sessionStorage.getItem('hrflow_user');
        let token = sessionStorage.getItem('hrflow_token');
        if (userStr) {
            try {
                let userObj = JSON.parse(userStr);
                config.headers['X-HR-User'] = userObj.name || userObj.email || "Unknown";
                config.headers['X-HR-Role'] = userObj.role || "HR_AGENT";
                config.headers['X-HR-Email'] = userObj.email || "";
            } catch(e) {}
        }
        if (token) {
            config.headers['Authorization'] = `Bearer ${token}`;
        }
    }
    return originalFetch(resource, config);
};

function buildAuthHeaders() {
    const headers = { "Content-Type": "application/json" };
    try {
        const raw = sessionStorage.getItem("hrflow_user") || localStorage.getItem("hrflow_last_user");
        const u = raw ? JSON.parse(raw) : {};
        if (u.name) headers["X-HR-User"] = u.name;
        if (u.role) headers["X-HR-Role"] = u.role;
        if (u.email) headers["X-HR-Email"] = u.email;
        const token = sessionStorage.getItem("hrflow_token");
        if (token) headers["Authorization"] = `Bearer ${token}`;
    } catch (_) {}
    return headers;
}


