function bindSidebarModuleNavigation() {
    document.querySelectorAll(".sidebar-nav .nav-item").forEach((item) => {
        item.addEventListener("click", async (e) => {
            const mod = item.getAttribute("data-module");
            if (mod === "dashboard" || mod === "tracker" || mod === "agent-workbench" || mod === "agents-status") {
                return; // allow normal page navigation to dashboard.html, agentworktracker.html, agent.html, or track.html
            }
            e.preventDefault();
            document.querySelectorAll(".sidebar-nav .nav-item").forEach((n) => n.classList.remove("active"));
            item.classList.add("active");
            if (mod && window.history && window.history.replaceState) {
                window.history.replaceState(null, "", `#${mod}`);
            }
            await switchWorkspaceModule(mod);
        });
    });
}

async function switchWorkspaceModule(mod) {
    if (currentRole === "HR_AGENT") {
        window.location.replace(`agent.html#${mod || "agent-workbench"}`);
        return;
    }
    const adminOnlyMods = ["users", "builder", "integrations", "audit"];
    if (currentRole !== "ADMIN" && adminOnlyMods.includes(mod)) {
        mod = "inbox";
        if (window.history && window.history.replaceState) {
            window.history.replaceState(null, "", "#inbox");
        }
    }

    activeModule = mod;
    const inboxView = document.getElementById("moduleInboxView");
    const opView = document.getElementById("moduleOperationalView");
    if (!inboxView || !opView) return;

    if (mod === "inbox") {
        inboxView.style.display = "flex";
        opView.style.display = "none";
        await loadGmailStatusAndMessages();
        return;
    }

    inboxView.style.display = "none";
    opView.style.display = "flex";


    if (mod === "departments") {
        await renderDepartmentsWorkspaceView(opView);
    } else if (mod === "users") {
        await renderUsersWorkspaceView(opView);
    } else if (mod === "cases") {

        await renderCasesWorkspaceView(opView);
    } else if (mod === "tasks") {
        await renderTasksWorkspaceView(opView);
    } else if (mod === "approvals") {
        await renderApprovalsWorkspaceView(opView);
    } else if (mod === "workflows" || mod === "builder") {
        renderBuildingInProgressView(opView, mod);
    } else if (mod === "actions") {
        await renderActionsWorkspaceView(opView);
    } else if (mod === "reports") {
        await renderReportsWorkspaceView(opView);
    } else if (mod === "integrations") {
        await renderIntegrationsWorkspaceView(opView);
    } else if (mod === "audit") {
        await renderAuditWorkspaceView(opView);
    }
}

